"""依 Wowhead 地城手冊（Dungeon Journal）補上缺的掉落、修正首領對應（可重複執行）。"""
import json, os, re
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SHARED = '全副本隨機（任一首領）'
RFC = [[272996,"穴居怪權杖",3,2,4,21,13,"奧格弗林特",11517],[272999,"野蠻之弩",3,2,18,26,13,"奧格弗林特",11517],[272998,"白骨指虎",3,2,13,21,13,"奧格弗林特",11517],[252778,"圖樣：陷捕者皮甲手套",3,9,1,0,0,"*",0],[252781,"圖樣：風暴飛騎皮甲手套",3,9,1,0,0,"*",0],[251364,"設計圖：十字軍手套",3,9,4,0,0,"*",0],[252782,"圖樣：智者皮甲手套",3,9,1,0,0,"*",0],[251362,"設計圖：保衛者手套",3,9,4,0,0,"*",0],[252780,"圖樣：圖騰師皮甲手套",3,9,1,0,0,"*",0],[253912,"圖樣：鑲絲閃耀禮袍",3,9,2,0,1,"*",0],[251341,"設計圖：守衛鍊甲衫",3,9,4,0,0,"*",0],[251360,"設計圖：精兵手套",3,9,4,0,0,"奧格弗林特",11517],[251363,"設計圖：侍僧手套",3,9,4,0,0,"*",0],[252777,"圖樣：打鬥者皮甲手套",3,9,1,0,0,"奧格弗林特",11517],[253902,"圖樣：鑲絲古樸禮袍",3,9,2,0,1,"*",0],[253906,"圖樣：鑲絲烈焰禮袍",3,9,2,0,1,"*",0],[253908,"圖樣：鑲絲暗影禮袍",3,9,2,0,1,"*",0],[253910,"圖樣：鑲絲珍珠禮袍",3,9,2,0,1,"*",0],[14148,"水晶腕輪",3,4,1,9,13,"饑餓者塔拉加曼",11520],[14149,"地下斗篷",3,4,-6,16,13,"饑餓者塔拉加曼",11520],[14145,"被詛咒的魔刃",3,2,7,21,13,"饑餓者塔拉加曼",11520],[253904,"圖樣：鑲絲絲柔禮袍",3,9,2,0,1,"*",0],[251361,"設計圖：守衛手套",3,9,4,0,0,"饑餓者塔拉加曼",11520],[252779,"圖樣：防衛者皮甲手套",3,9,1,0,0,"饑餓者塔拉加曼",11520],[15508,"步兵斗篷",2,4,-6,16,14,"饑餓者塔拉加曼",11520],[14150,"招魂法袍",3,4,1,20,13,"祈求者耶戈什",11518],[14147,"洞穴護腕",3,4,3,9,13,"祈求者耶戈什",11518],[14151,"聖歌之刃",3,2,15,13,13,"祈求者耶戈什",11518],[273005,"薩特皮披風",3,4,-6,16,13,"巴札蘭",11519],[273003,"灼熱匕首",3,2,15,21,13,"巴札蘭",11519],[273007,"裂谷步靴",3,4,2,8,13,"巴札蘭",11519]]
ADD = {'sfk': [[6641,"鬼魂之刃",3,2,8,17,22,"死亡之誓",3872],[6642,"幻影之甲",3,4,3,5,22,"死亡之誓",3872]],
       'stocks': [[720,"打鬥者手套",3,4,2,10,23,"巴基爾·斯瑞德",1716]],
       'rfk-ruin': [[273103,"藍圖：秘法回收機",2,9,8,0,None,"拉斯梅爾",250657]]}
FIX = {('sfk', 6341): '指揮官斯普林瓦爾', ('sm-arm', 10330): '赫洛德', ('sm-cath', 10330): '血色十字軍指揮官莫格萊尼'}
row = lambda r: [r[0], r[1], r[2], r[3], r[4], r[5], r[6] or None, SHARED if r[7] == '*' else r[7], '', r[8]]
for p in ['index.html', 'claude-artifact/index.html']:
    path = os.path.join(ROOT, p); s = open(path, encoding='utf-8').read()
    m = re.search(r'const RAW_LOOT = (\{.*?\});\n', s); R = json.loads(m.group(1))
    R['rfc'] = [row(r) for r in RFC]
    for k, rows in ADD.items():
        have = {x[0] for x in R.get(k, [])}
        R.setdefault(k, []).extend(row(r) for r in rows if r[0] not in have)
    for (k, iid), b in FIX.items():
        for x in R.get(k, []):
            if x[0] == iid: x[7] = b
    s = s[:m.start()] + 'const RAW_LOOT = ' + json.dumps(R, ensure_ascii=False, separators=(',', ':')) + ';\n' + s[m.end():]
    if '"rfc":[' not in s.split('const BOSS_ORDER = {')[1][:6000]:
        s = s.replace('const BOSS_ORDER = {\n', 'const BOSS_ORDER = {\n  "rfc":["奧格弗林特","饑餓者塔拉加曼","祈求者耶戈什","巴札蘭","%s"],\n' % SHARED, 1)
    open(path, 'w', encoding='utf-8').write(s); print(p, 'rfc', len(R['rfc']))
